create extension if not exists pgcrypto;
create type public.channel_type as enum ('source','destination');
create type public.publish_mode as enum ('copy','forward');
create type public.message_status as enum ('pending','posted','failed','deleted');
create type public.user_role as enum ('admin','viewer');
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,role public.user_role not null default 'viewer',created_at timestamptz not null default now());
create table public.channels(id uuid primary key default gen_random_uuid(),type public.channel_type not null,title text not null,telegram_chat_id bigint unique not null,username text,is_active boolean not null default true,can_post boolean not null default false,can_delete boolean not null default false,last_permission_check_at timestamptz,last_error text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.posts(id uuid primary key default gen_random_uuid(),source_channel_id uuid references public.channels(id) on delete set null,source_message_id bigint,telegram_update_id bigint unique,text text,caption text,media_type text not null default 'text',media_url text,telegram_file_id text,status text not null default 'new',created_at timestamptz not null default now());
create table public.post_channel_matches(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,destination_channel_id uuid not null references public.channels(id) on delete cascade,variant_text text,created_at timestamptz not null default now(),unique(post_id,destination_channel_id));
create table public.published_messages(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,destination_channel_id uuid not null references public.channels(id) on delete cascade,telegram_message_id bigint,publish_mode public.publish_mode not null default 'copy',status public.message_status not null default 'pending',posted_at timestamptz,deleted_at timestamptz,error_message text,created_at timestamptz not null default now(),unique(post_id,destination_channel_id));
create table public.scheduled_publications(id uuid primary key default gen_random_uuid(),post_id uuid not null references public.posts(id) on delete cascade,destination_channel_id uuid not null references public.channels(id) on delete cascade,scheduled_at timestamptz not null,status text not null default 'pending',created_at timestamptz not null default now());
create table public.app_settings(id int primary key default 1 check(id=1),telegram_bot_token text,telegram_webhook_secret text,max_channels_per_post int not null default 3 check(max_channels_per_post between 1 and 20),updated_at timestamptz not null default now());
create index posts_created_at_idx on public.posts(created_at desc);create index published_created_at_idx on public.published_messages(created_at desc);create index scheduled_due_idx on public.scheduled_publications(status,scheduled_at);
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin') $$;
alter table public.profiles enable row level security;alter table public.channels enable row level security;alter table public.posts enable row level security;alter table public.post_channel_matches enable row level security;alter table public.published_messages enable row level security;alter table public.scheduled_publications enable row level security;alter table public.app_settings enable row level security;
create policy profiles_self on public.profiles for select using(id=auth.uid() or public.is_admin());
create policy viewer_read_channels on public.channels for select using(auth.uid() is not null);create policy admin_write_channels on public.channels for all using(public.is_admin()) with check(public.is_admin());
create policy viewer_read_posts on public.posts for select using(auth.uid() is not null);create policy admin_write_posts on public.posts for all using(public.is_admin()) with check(public.is_admin());
create policy viewer_read_matches on public.post_channel_matches for select using(auth.uid() is not null);create policy admin_write_matches on public.post_channel_matches for all using(public.is_admin()) with check(public.is_admin());
create policy viewer_read_published on public.published_messages for select using(auth.uid() is not null);create policy admin_write_published on public.published_messages for all using(public.is_admin()) with check(public.is_admin());
create policy viewer_read_scheduled on public.scheduled_publications for select using(auth.uid() is not null);create policy admin_write_scheduled on public.scheduled_publications for all using(public.is_admin()) with check(public.is_admin());
create policy admin_settings on public.app_settings for all using(public.is_admin()) with check(public.is_admin());
insert into public.app_settings(id) values(1) on conflict do nothing;
